const inputData = $input.first().json;
const sheetData = $('Google Sheets Trigger').first().json;

// Get the raw values from your inputs
const inOutStr = sheetData['IN/Out'] || inputData['IN/Out'];
const dateStr = sheetData['Date '] || sheetData['Date'] || inputData['Date'];
const sproutLink = inputData['Sprout Link'];
const schedule = inputData['PT/FT Schedule']; // Fetched in case you need it for future logic

// 1. Determine LogType (IN = 0, OUT = 1)
// We will store the types in an array to handle the "Both" scenario
let logTypes = []; 

if (inOutStr && typeof inOutStr === 'string') {
    const typeNormalized = inOutStr.trim().toUpperCase();
    if (typeNormalized === 'BOTH') {
        // If "Both", we need both an IN (0) and an OUT (1) log
        logTypes = [0, 1];
    } else if (typeNormalized === 'OUT') {
        logTypes = [1];
    } else if (typeNormalized === 'IN') {
        logTypes = [0];
    } else {
        // Default to IN if unrecognized
        logTypes = [0];
    }
} else {
    // Default to IN if missing
    logTypes = [0];
}

// 2. Format LogTime
// Validates the date from the Google Sheet and converts it to ISO8601 format.
// If it fails to parse, it falls back to the raw string provided by the sheet.
let logTime = dateStr;
if (dateStr) {
    const parsedDate = new Date(dateStr);
    if (!isNaN(parsedDate.getTime())) {
        logTime = parsedDate.toISOString(); 
    }
}

// 3. Determine EmployeeId
// Extracts the ID from the "Sprout Link" query parameters
// (e.g., "https://doneverse.hrhub.ph/Employee.aspx?id=21582&..." -> "21582").
let employeeId = sproutLink;
if (sproutLink && typeof sproutLink === 'string') {
    try {
        const url = new URL(sproutLink);
        const id = url.searchParams.get('id');
        if (id) {
            employeeId = id;
        }
    } catch (e) {
        // Fallback for malformed or relative URLs
        const match = sproutLink.match(/[?&]id=([^&]+)/);
        if (match) {
            employeeId = match[1];
        }
    }
}

// 4. Construct the Details array
// Map over the determined logTypes to create the objects for the Details array
const detailsArray = logTypes.map(type => {
    return {
        LogType: type,
        LogTime: logTime // Note: If "Both", both IN and OUT will have the exact same timestamp currently.
    };
});

// 5. Construct the final required output structure
const output = {
    EmployeeId: employeeId,
    Details: detailsArray
};

// Return the constructed payload
// (If using an older version of n8n, you might need to use: return [{ json: output }]; )
return output;

