const inputData = $input.first().json;
const sheetData = $('Google Sheets Trigger').first().json;

// Helper to safely get values even if column names have spaces
function getValue(obj, possibleKeys) {
    for (const key of possibleKeys) {
        if (obj[key] !== undefined && obj[key] !== null && obj[key] !== '') {
            return obj[key];
        }
    }
    return undefined;
}

// Get the raw values from your inputs
const inOutStr = getValue(sheetData, ['IN/Out']) || getValue(inputData, ['IN/Out']);

const dateFromStr =
    getValue(sheetData, ['Date From', 'Date From ']) ||
    getValue(inputData, ['Date From', 'Date From ']);

const dateToStr =
    getValue(sheetData, ['Date To', 'Date To ']) ||
    getValue(inputData, ['Date To', 'Date To ']);

const sproutLink = inputData['Sprout Link'];
const schedule = inputData['PT/FT Schedule'];

// Helper function to format dates safely
function formatDateToISO(rawDate) {
    if (!rawDate) return rawDate;

    let parsedDate;

    const dmyPattern = /^(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{4})(.*)$/;
    const match = rawDate.toString().trim().match(dmyPattern);

    if (match) {
        const day = match[1].padStart(2, '0');
        const month = match[2].padStart(2, '0');
        const year = match[3];
        const timePart = match[4].trim();

        const isoDateString = `${year}-${month}-${day}`;

        if (timePart) {
            parsedDate = new Date(`${isoDateString} ${timePart}`);
        } else {
            parsedDate = new Date(`${isoDateString}T00:00:00`);
        }
    } else {
        parsedDate = new Date(rawDate);
    }

    if (!isNaN(parsedDate.getTime())) {
        return parsedDate.toISOString();
    }

    return rawDate;
}

// 1. Determine LogType IN = 0, OUT = 1
let logType = 0;

if (inOutStr && typeof inOutStr === 'string') {
    const typeNormalized = inOutStr.trim().toUpperCase();

    if (typeNormalized === 'OUT') {
        logType = 1;
    } else if (typeNormalized === 'IN') {
        logType = 0;
    }
}

// 2. Format Date From and Date To
const dateFrom = formatDateToISO(dateFromStr);
const dateTo = formatDateToISO(dateToStr);

// Use Date From as LogTime
const logTime = dateFrom;

// 3. Determine EmployeeId
let employeeId = sproutLink;

if (sproutLink && typeof sproutLink === 'string') {
    try {
        const url = new URL(sproutLink);
        const id = url.searchParams.get('id');

        if (id) {
            employeeId = id;
        }
    } catch (e) {
        const match = sproutLink.match(/[?&]id=([^&]+)/);

        if (match) {
            employeeId = match[1];
        }
    }
}

// 4. Construct the final output structure
const output = {
    EmployeeId: employeeId,

    // These will now appear in the output
    DateFrom: dateFrom,
    DateTo: dateTo,

    Details: [
        {
            LogType: logType,
            LogTime: logTime
        }
    ]
};

return output;
